def _mk_q1(sc):
    def g(rng):
        p = F._q1(rng, sc)
        p["stimulus"]["description"] = sc["intro"].format(n=sc["n"]) + " " + p["stimulus"]["description"]
        return p
    g.__name__ = f"bif_q1_{sc['key']}"
    g.__module__ = __name__
    return g


